INSERT INTO `m_course_sections` VALUES
(107,1,1,NULL,'',1,'',1,NULL,NULL,NULL,1790869186),
(108,24,0,'📋 Accueil & Cadrage','<p><strong>Bienvenue dans ce cours !</strong></p>\n<p>Cette section présente le cours : objectifs pédagogiques, compétences couvertes, durée estimée, prérequis, mode d\'emploi de la plateforme et lien vers l\'aide.</p>\n<p>Lisez bien ces informations avant de commencer. Elles vous aideront à choisir votre voie : <em>Formation complète</em> ou <em>Examen direct</em>.</p>',1,'26',1,NULL,NULL,NULL,1790929467),
(109,24,1,'📝 Pré-test de positionnement','<p>Ce test rapide (10 à 15 questions) évalue votre niveau <strong>avant</strong> la formation.</p>\n<p>Il n\'a aucune incidence sur votre attestation : il sert à mesurer vos progrès à la fin du cours. <strong>En session avec un formateur, il est obligatoire.</strong></p>',1,'94',1,NULL,NULL,NULL,1790929467),
(110,24,2,'🎓 Séquences d\'apprentissage','<p>Chaque séquence couvre une compétence du référentiel :</p>\n<ul>\n  <li>🎬 Vidéo courte (3 à 7 minutes)</li>\n  <li>📄 Fiche mémo PDF téléchargeable</li>\n  <li>🎮 Activité interactive (H5P)</li>\n  <li>✅ Quiz d\'entraînement (disponible hors ligne)</li>\n</ul>\n<p>Ces séquences sont <strong>recommandées</strong> mais facultatives si vous passez par la voie Examen direct.</p>',1,'',1,NULL,NULL,NULL,1790929467),
(111,24,3,'🏆 Examen final','<p>C\'est l\'épreuve qui déclenche l\'attestation si vous réussissez.</p>\n<ul>\n  <li>Questions tirées aléatoirement dans la banque de questions</li>\n  <li>Durée limitée — minuteur visible à l\'écran</li>\n  <li>Seuil de réussite : <strong>70 %</strong> minimum</li>\n  <li><strong>2 tentatives maximum</strong> (voie Examen direct)</li>\n</ul>\n<p>Une connexion internet est requise pour passer cet examen.</p>',1,'95',1,NULL,NULL,NULL,1790929467),
(112,24,4,'📊 Enquête de satisfaction','<p>Merci de répondre à cette courte enquête (5 à 8 questions) avant de télécharger votre attestation.</p>\n<p>Vos réponses sont anonymes et permettent d\'améliorer les formations du programme PACTDIGITAL-BF.</p>',1,'96',1,NULL,NULL,NULL,1790929467),
(113,25,0,'📋 Accueil & Cadrage','<p><strong>Bienvenue dans ce cours !</strong></p>\n<p>Cette section présente le cours : objectifs pédagogiques, compétences couvertes, durée estimée, prérequis, mode d\'emploi de la plateforme et lien vers l\'aide.</p>\n<p>Lisez bien ces informations avant de commencer. Elles vous aideront à choisir votre voie : <em>Formation complète</em> ou <em>Examen direct</em>.</p>',1,'27',1,NULL,NULL,NULL,1790929531),
(114,25,1,'📝 Pré-test de positionnement','<p>Ce test rapide (10 à 15 questions) évalue votre niveau <strong>avant</strong> la formation.</p>\n<p>Il n\'a aucune incidence sur votre attestation : il sert à mesurer vos progrès à la fin du cours. <strong>En session avec un formateur, il est obligatoire.</strong></p>',1,'99',1,NULL,NULL,NULL,1790929531),
(115,25,2,'🎓 Séquences d\'apprentissage','<p>Chaque séquence couvre une compétence du référentiel :</p>\n<ul>\n  <li>🎬 Vidéo courte (3 à 7 minutes)</li>\n  <li>📄 Fiche mémo PDF téléchargeable</li>\n  <li>🎮 Activité interactive (H5P)</li>\n  <li>✅ Quiz d\'entraînement (disponible hors ligne)</li>\n</ul>\n<p>Ces séquences sont <strong>recommandées</strong> mais facultatives si vous passez par la voie Examen direct.</p>',1,'',1,NULL,NULL,NULL,1790929531),
(116,25,3,'🏆 Examen final','<p>C\'est l\'épreuve qui déclenche l\'attestation si vous réussissez.</p>\n<ul>\n  <li>Questions tirées aléatoirement dans la banque de questions</li>\n  <li>Durée limitée — minuteur visible à l\'écran</li>\n  <li>Seuil de réussite : <strong>70 %</strong> minimum</li>\n  <li><strong>2 tentatives maximum</strong> (voie Examen direct)</li>\n</ul>\n<p>Une connexion internet est requise pour passer cet examen.</p>',1,'100',1,NULL,NULL,NULL,1790929531),
