(91,'H5P.GuessTheAnswer','Guess the Answer',1,5,18,1,0,'iframe','guess-the-answer.js','guess-the-answer.css','','[\n  {\n    \"label\": \"Task description\",\n    \"importance\": \"medium\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Describe how the user should solve the task.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"importance\": \"medium\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      }\n    ]\n  },\n  {\n    \"label\": \"Descriptive solution label\",\n    \"importance\": \"low\",\n    \"name\": \"solutionLabel\",\n    \"type\": \"text\",\n    \"widget\": \"textarea\",\n    \"default\": \"Click to see the answer.\",\n    \"description\": \"Clickable text area where the solution will be displayed.\",\n    \"optional\": true\n  },\n  {\n    \"label\": \"Solution text\",\n    \"importance\": \"high\",\n    \"name\": \"solutionText\",\n    \"type\": \"text\",\n    \"widget\": \"textarea\",\n    \"description\": \"The solution for the picture.\"\n  }\n]',NULL,1,28,NULL,'https://h5p.org/tutorial-guess-the-answer','https://h5p.org/guess-the-answer',1),
