(124,'H5P.KewArCode','KewAr Code',1,2,2,1,0,'iframe','dist/h5p-kewar-code.js','dist/h5p-kewar-code.css','','[\n  {\n    \"name\": \"introduction\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"label\": \"Introductory text\",\n    \"importance\": \"medium\",\n    \"optional\": true,\n    \"description\": \"This text can optionally be presented along with your code.\",\n    \"enterMode\": \"div\",\n    \"tags\": [\n      \"sub\",\n      \"sup\",\n      \"strong\",\n      \"em\",\n      \"p\",\n      \"code\",\n      \"u\",\n      \"del\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h1\",\n      \"h2\",\n      \"h3\",\n      \"h4\",\n      \"h5\",\n      \"h6\",\n      \"pre\",\n      \"hr\",\n      \"table\"\n    ],\n    \"font\": {\n      \"size\": true,\n      \"color\": true,\n      \"background\": true\n    }\n  },\n  {\n    \"name\": \"codeType\",\n    \"type\": \"select\",\n    \"label\": \"Code type\",\n    \"description\": \"Select what kind of code you want to generate\",\n    \"options\": [\n      {\n        \"value\": \"contact\",\n        \"label\": \"Contact\"\n      },\n      {\n        \"value\": \"event\",\n        \"label\": \"Event\"\n      },\n      {\n        \"value\": \"email\",\n        \"label\": \"Email address\"\n      },\n      {\n        \"value\": \"h5p\",\n        \"label\": \"H5P\"\n      },\n      {\n        \"value\": \"location\",\n        \"label\": \"Location\"\n      },\n      {\n        \"value\": \"phone\",\n        \"label\": \"Phone number\"\n      },\n      {\n        \"value\": \"sms\",\n        \"label\": \"SMS\"\n      },\n      {\n        \"value\": \"text\",\n        \"label\": \"Text\"\n      },\n      {\n        \"value\": \"url\",\n        \"label\": \"URL\"\n      }\n    ],\n    \"default\": \"url\",\n    \"widget\": \"editorKewArCode\"\n  },\n  {\n    \"name\": \"contact\",\n    \"type\": \"group\",\n    \"label\": \"Contact\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"name\",\n        \"type\": \"text\",\n        \"label\": \"Name\",\n        \"placeholder\": \"John Smith\",\n        \"maxLength\": 150\n      },\n      {\n        \"name\": \"organization\",\n        \"type\": \"text\",\n        \"label\": \"Organization\",\n        \"placeholder\": \"H5P fan club\",\n        \"optional\": true,\n        \"maxLength\": 150\n      },\n      {\n        \"name\": \"title\",\n        \"type\": \"text\",\n        \"label\": \"Title\",\n        \"placeholder\": \"Master of None\",\n        \"optional\": true,\n        \"maxLength\": 100\n      },\n      {\n        \"name\": \"number\",\n        \"type\": \"text\",\n        \"label\": \"Phone number\",\n        \"description\": \"Phone number (please use the format +12 345 67890)\",\n        \"placeholder\": \"+12 345 67890\",\n        \"optional\": true,\n        \"regexp\": {\n          \"pattern\": \"^\\\\+[0-9]{1,3}[\\\\ ]?[0-9]{1,4}[\\\\ ]?[0-9]{1,8}$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"email\",\n        \"type\": \"text\",\n        \"label\": \"Email address\",\n        \"description\": \"Email address to write message to\",\n        \"placeholder\": \"john@fictional-h5p-fan-club.org\",\n        \"optional\": true,\n        \"maxLength\": 150,\n        \"regexp\": {\n          \"pattern\": \"^[A-Z0-9\\\\._%+-]+@[A-Z0-9.-]+\\\\.[A-Z]{2,}$\",\n          \"modifiers\": \"i\"\n        }\n      },\n      {\n        \"name\": \"address\",\n        \"type\": \"group\",\n        \"label\": \"Address\",\n        \"importance\": \"medium\",\n        \"expanded\": true,\n        \"fields\": [\n          {\n            \"name\": \"extended\",\n            \"type\": \"text\",\n            \"label\": \"Extended address\",\n            \"description\": \"c/o information, etc.\",\n            \"placeholder\": \"c/o H5P Fan Club\",\n            \"optional\": true,\n            \"maxLength\": 150\n          },\n  