(140,'H5P.InfoWall','Information Wall',0,4,9,1,0,'iframe','dist/h5p-info-wall.js','dist/h5p-info-wall.css','','[\n  {\n    \"name\": \"infoWall\",\n    \"type\": \"group\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"widget\": \"infoWall\",\n    \"fields\": [\n      {\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"label\": \"Header\",\n        \"description\": \"Optional header for the information wall.\",\n        \"importance\": \"high\",\n        \"optional\": true\n      },\n      {\n        \"name\": \"propertiesGroup\",\n        \"type\": \"group\",\n        \"label\": \"Properties\",\n        \"importance\": \"high\",\n        \"expanded\": false,\n        \"fields\": [\n          {\n            \"name\": \"properties\",\n            \"type\": \"list\",\n            \"label\": \"Properties\",\n            \"description\": \"Properties for the entries\",\n            \"importance\": \"high\",\n            \"entity\": \"property\",\n            \"min\": 1,\n            \"widgets\": [\n              {\n                \"name\": \"VerticalTabs\",\n                \"label\": \"Default\"\n              }\n            ],\n            \"field\": {\n              \"name\": \"propertyItems\",\n              \"type\": \"group\",\n              \"label\": \"Property items\",\n              \"fields\": [\n                {\n                  \"name\": \"label\",\n                  \"type\": \"text\",\n                  \"label\": \"Label\",\n                  \"default\": \"Unnamed\"\n                },\n                {\n                  \"name\": \"showLabel\",\n                  \"type\": \"boolean\",\n                  \"label\": \"Show property label\",\n                  \"default\": false,\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"searchInProperty\",\n                  \"type\": \"boolean\",\n                  \"label\": \"Enable searching in the property\",\n                  \"default\": true,\n                  \"optional\": true\n                },\n                {\n                  \"name\": \"styling\",\n                  \"type\": \"group\",\n                  \"label\": \"Styling override\",\n                  \"fields\": [\n                    {\n                      \"name\": \"bold\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Bold\",\n                      \"optional\": true\n                    },\n                    {\n                      \"name\": \"italic\",\n                      \"type\": \"boolean\",\n                      \"label\": \"Italic\",\n                      \"optional\": true\n                    }\n                  ]\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"dummy\",\n            \"type\": \"text\",\n            \"widget\": \"none\"\n          }\n        ]\n      },\n      {\n        \"name\": \"panels\",\n        \"type\": \"list\",\n        \"label\": \"Panels\",\n        \"description\": \"Panels for the wall\",\n        \"importance\": \"high\",\n        \"entity\": \"panel\",\n        \"min\": 1,\n        \"widgets\": [\n          {\n            \"name\": \"VerticalTabs\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"field\": {\n          \"name\": \"entriesGroup\",\n          \"type\": \"group\",\n          \"label\": \"Entry items\",\n          \"fields\": [\n            {\n              \"name\": \"panelTitle\",\n              \"type\": \"text\",\n              \"label\": \"Title for panel\"\n            },\n            {\n              \"name\": \"image\",\n              \"type\": \"library\",\n              \"label\": \"Image\",\n              \"optional\": true,\n              \"options\": [\n                \"H5P.Image 1.1\"\n              ]\n            },\n            {\n              \"name\": \"entries\",\n              \"type\": \"list\",\n              \"label\": \"Entries\",\n              \"description\": \"Entries for the properties\",\n              \"entity\": \"value\",\n              \"widgets\": [\n                {\n                  \"name\": \"InfoWallPassiveList\",\n                  \"label\": \"Default\"\n                }\n              ],\n              \"min\": 1,\n              \"field\": {\n                \"name\": \"value\",\n                \"type\": \"text\",\n                \"widget\": \"html\",\n                \"label\": \"Label to be changed automatically\",\n                \"optional\": true,\n                \"enterMode\": \"div\",\n                \"tags\": [\n                  \"strong\",\n                  \"em\",\n                  \"u\",\n                  \"del\",\n                  \"sub\",\n                  \"sup\",\n                  \"a\",\n                  \"ul\",\n                  \"ol\",\n                  \"h1\",\n                  \"h2\",\n                  \"h3\",\n                  \"h4\",\n                  \"h5\",\n                  \"h6\",\n                  \"hr\",\n                  \"pre\",\n                  \"code\",\n                  \"table\"\n                ],\n                \"font\": {\n                  \"size\": true,\n                  \"color\": true,\n                  \"background\": true\n                }\n              }\n            },\n            {\n              \"name\": \"keywords\",\n              \"type\": \"text\",\n              \"label\": \"Additional keywords\",\n              \"description\": \"Add additional keywords separated by a blank space that will be used for filtering but not be visible to the user.\",\n              \"optional\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"behaviour\",\n        \"type\": \"group\",\n        \"importance\": \"low\",\n        \"label\": \"Behavioural settings\",\n        \"description\": \"These options will let you control how the task behaves.\",\n        \"fields\": [\n          {\n            \"name\": \"useFallbackImage\",\n            \"type\": \"boolean\",\n            \"label\": \"Use fallback for missing images\",\n            \"default\": false,\n            \"optional\": true\n          },\n          {\n            \"name\": \"fallbackImage\",\n            \"type\": \"library\",\n            \"label\": \"Image\",\n            \"optional\": true,\n            \"options\": [\n              \"H5P.Image 1.1\"\n            ],\n            \"widget\": \"showWhen\",\n            \"showWhen\": {\n              \"rules\": [\n                {\n                  \"field\": \"useFallbackImage\",\n                  \"equals\": true\n                }\n              ]\n            }\n          },\n          {\n            \"name\": \"imageWidth\",\n            \"label\": \"Image width\",\n            \"type\": \"number\",\n            \"importance\": \"low\",\n            \"description\": \"Image width in px.\",\n            \"default\": 150\n          },\n          {\n            \"name\": \"imageHeight\",\n            \"label\": \"Image height\",\n            \"type\": \"number\",\n            \"importance\": \"low\",\n            \"description\": \"Image height in px.\",\n            \"default\": 150\n          },\n          {\n            \"name\": \"alternateBackground\",\n            \"label\": \"Alternate panel background\",\n            \"type\": \"boolean\",\n            \"importance\": \"low\",\n            \"description\": \"If checked, each 2nd panel will have slightly darker background than the others.\",\n            \"default\": true,\n            \"optional\": true\n          },\n          {\n            \"name\": \"offerFilterField\",\n            \"label\": \"Offer filter field\",\n            \"type\": \"boolean\",\n            \"importance\": \"low\",\n            \"description\": \"If checked, users will be able to filter the info wall.\",\n            \"default\": true,\n            \"optional\": true\n          },\n          {\n            \"name\": \"modeFilterField\",\n            \"label\": \"Mode for filter field\",\n            \"type\": \"select\",\n            \"importance\": \"low\",\n            \"description\": \"Choose whether the filter should narrow down or broaden the search with every new keyword.\",\n            \"options\": [\n              {\n                \"value\": \"and\",\n                \"label\": \"Narrow down\"\n              },\n              {\n                \"value\": \"or\",\n                \"label\": \"Broaden\"\n              }\n            ],\n            \"default\": \"or\",\n            \"optional\": false,\n            \"widget\": \"showWhen\",\n            \"showWhen\": {\n              \"rules\": [\n                {\n                  \"field\": \"offerFilterField\",\n                  \"equals\": true\n                }\n              ]\n            }\n          }\n        ]\n      },\n      {\n        \"name\": \"l10n\",\n        \"type\": \"group\",\n        \"common\": true,\n        \"label\": \"User interface\",\n        \"importance\": \"low\",\n        \"fields\": [\n          {\n            \"name\": \"noEntriesError\",\n            \"type\": \"text\",\n            \"label\": \"No content entered\",\n            \"importance\": \"low\",\n            \"default\": \"The author did not enter anything.\"\n          },\n          {\n            \"name\": \"noMatchesForFilter\",\n            \"type\": \"text\",\n            \"label\": \"No matches found\",\n            \"description\": \"@query is a placeholder and will be replaced by the respective query that was entered.\",\n            \"importance\": \"low\",\n            \"default\": \"There are not matches for @query.\"\n          },\n          {\n            \"name\": \"enterToFilter\",\n            \"type\": \"text\",\n            \"label\": \"Enter to filter\",\n            \"description\": \"Message for screen readers.\",\n            \"importance\": \"low\",\n            \"default\": \"Enter a query to filter the content for relevant entries.\"\n          },\n          {\n            \"name\": \"listChanged\",\n            \"type\": \"text\",\n            \"label\": \"List changed.\",\n            \"description\": \"Message for screen readers. @visible and @total are placeholders and will be preplaced with the respective values.\",\n            \"importance\": \"low\",\n            \"default\": \"List changed. Showing @visible of @total items.\"\n          }\n        ]\n      }\n    ]\n  }\n]',NULL,NULL,NULL,NULL,NULL,'https://h5p.org/content-types/information-wall',1),
