ses\",\"default\":true,\"optional\":true}]},{\"name\":\"ambient\",\"type\":\"group\",\"importance\":\"low\",\"label\":\"Events\",\"fields\":[{\"name\":\"clickStageLocked\",\"type\":\"audio\",\"label\":\"Click on locked stage\",\"description\":\"Will be played on the map when clicking on a locked stage.\",\"optional\":true},{\"name\":\"checkExerciseNotFullScore\",\"type\":\"audio\",\"label\":\"Check exercise (not full score)\",\"description\":\"Will be played when an answer is checked and the user did not get full score.\",\"optional\":true},{\"name\":\"checkExerciseFullScore\",\"type\":\"audio\",\"label\":\"Check exercise (full score)\",\"description\":\"Will be played when an answer is checked and the user did get full score.\",\"optional\":true},{\"name\":\"unlockStage\",\"type\":\"audio\",\"label\":\"Unlocking a stage\",\"description\":\"Will be played on the map when a stage gets unlocked.\",\"optional\":true},{\"name\":\"openExercise\",\"type\":\"audio\",\"label\":\"Open exercise\",\"description\":\"Will be played when an exercise is opened.\",\"optional\":true},{\"name\":\"closeExercise\",\"type\":\"audio\",\"label\":\"Close exercise\",\"description\":\"Will be played when an exercise is closed.\",\"optional\":true},{\"name\":\"showDialog\",\"type\":\"audio\",\"label\":\"Show dialog\",\"description\":\"Will be played when a confirmation dialog is shown.\",\"optional\":true},{\"name\":\"fullScore\",\"type\":\"audio\",\"label\":\"Full score\",\"description\":\"Will be played when the user reaches full score for the map.\",\"optional\":true},{\"name\":\"lostLife\",\"type\":\"audio\",\"label\":\"Lost a life\",\"description\":\"Will be played when the user loses a life.\",\"optional\":true},{\"name\":\"gainedLife\",\"type\":\"audio\",\"label\":\"Gained life\",\"description\":\"Will be played when the user gains a life.\",\"optional\":true},{\"name\":\"gameOver\",\"type\":\"audio\",\"label\":\"Game over\",\"description\":\"Will be played when the user is game over.\