bleRetry\",\"label\":\"Enable \\\"Retry\\\" button\",\"type\":\"boolean\",\"default\":true,\"optional\":true},{\"name\":\"enableSolutionsButton\",\"label\":\"Enable \\\"Show solutions\\\" button\",\"type\":\"boolean\",\"default\":true,\"optional\":true},{\"name\":\"map\",\"type\":\"group\",\"label\":\"Map\",\"fields\":[{\"name\":\"showLabels\",\"type\":\"boolean\",\"label\":\"Show stage labels\",\"description\":\"Choose whether a stage\'s label will be shown on hovering a stage with the mouse. The label will not show on touch devices.\",\"default\":true},{\"name\":\"roaming\",\"type\":\"select\",\"label\":\"Roaming\",\"description\":\"Choose whether users can roam all stages freely, need to finish a stage to get access to that stage\'s neighbors, or need to pass a stage to get access to that stage\'s neigbors.\",\"options\":[{\"value\":\"free\",\"label\":\"Roam freely\"},{\"value\":\"complete\",\"label\":\"Complete to clear stage\"},{\"value\":\"success\",\"label\":\"Succeed to clear stage\"}],\"default\":\"free\"},{\"name\":\"fog\",\"type\":\"select\",\"label\":\"Visibility range\",\"description\":\"Select how far the user can see ahead\",\"optional\":true,\"options\":[{\"value\":\"all\",\"label\":\"See all stages\"},{\"value\":\"1\",\"label\":\"See all unlocked stages and their adjacent neighbors\"},{\"value\":\"0\",\"label\":\"See only unlocked stages\"}],\"default\":\"all\",\"widget\":\"gamemapshowwhen\",\"gamemapshowwhen\":{\"nullWhenHidden\":true,\"rules\":[{\"field\":\"roaming\",\"equals\":[\"complete\",\"success\"]}]}}]}]},{\"name\":\"l10n\",\"type\":\"group\",\"label\":\"User interface\",\"common\":true,\"fields\":[{\"name\":\"start\",\"type\":\"text\",\"label\":\"Start\",\"default\":\"Start\"},{\"name\":\"continue\",\"type\":\"text\",\"label\":\"Continue\",\"default\":\"Continue\"},{\"name\":\"restart\",\"type\":\"text\",\"label\":\"Restart\",\"default\":\"Restart\"},{\"name\":\"showSolutions\",\"type\":\"text\",\"label\":\"Show solutions\",\"default\":\"Show solutions\"},{\"name\":\"completedMap\",\"type\":\"text\",\"label\":\"Completed the map\",\"default\":\"You have completed the map!\"},{\"name\":\"fullScoreButnoLivesLeft\",\"type\":\"text\",\"label\":\"Full score, but no lives left\",\"default\":\"You have achieved full score, but lost all your lifes!\"},{\"name\":\"fullScoreButTimeout\",\"type\":\"text\",\"label\":\"Full score, but timed out\",\"default\":\"You have achieved full score, but ran out of time!\"},{\"name\":\"confirmFinishHeader\",\"type\":\"text\",\"label\":\"Dialog header finish map\",\"default\":\"Finish map?\"},{\"name\":\"confirmFinishDialog\",\"type\":\"text\",\"label\":\"Dialog text finish map: General\",\"default\":\"If you finish now, you will not be able to explore the map any longer.\"},{\"name\":\"confirmFinishDialogSubmission\",\"type\":\"text\",\"label\":\"Dialog text finish map: Submission\",\"default\":\"Your score will be submitted.\"},{\"name\":\"confirmFinishDialogQuestion\",\"type\":\"text\",\"label\":\"Dialog text finish map: Question\",\"default\":\"Do you really want to finish the map?\"},{\"name\":\"confirmAccessDeniedHeader\",\"type\":\"text\",\"label\":\"Dialog header access denied\",\"default\":\"Stage locked\"},{\"name\":\"confirmAccessDeniedDialog\",\"type\":\"text\",\"label\":\"Dialog text access denied: General\",\"default\":\"This stage requires you to meet some goals before it can be opened.\"},{\"name\":\"yes\",\"type\":\"text\",\"label\":\"Yes\",\"default\":\"Yes\"},{\"name\":\"no\",\"type\":\"text\",\"label\":\"No\",\"default\":\"No\"},{\"name\":\"confirmGameOverHeader\",\"type\":\"text\",\"label\":\"Dialog header game over\",\"default\":\"Game over!\"},{\"name\":\"confirmGameOverDialog\",\"type\":\"text\",\"label\":\"Dialog text game over\",\"default\":\"You have lost all your lives. Please try again!\"},{\"name\":\"confirmGameOverDialogTimeout\",\"type\":\"text\",\"label\":\"Dialog text game over by timeout\",\"default\":\"You have run out of time. Please try again!\"},{\"name\":\"confirmTimeoutHeader\",\"type\":\"text\",\"label\":\"Dialog header time out\",\"default\":\"Time out!\"},{\"name\":\"confirmTimeoutDialog\",\"type\":\"text\",\"label\":\"Dialog text time out\",\"default\":\"You ran out of time.\"},{\"name\":\"confirmTimeoutDialogLostLife\",\"type\":\"text\",\"label\":\"Dialog text time out (lost a life)\",\"default\":\"You ran out of time and lost a life.\"},{\"name\":\"confirmScoreIncompleteHeader\",\"type\":\"text\",\"label\":\"Dialog header score incomplete\",\"default\":\"Not full score!\"},{\"name\":\"confirmIncompleteScoreDialogLostLife\",\"type\":\"text\",\"label\":\"Dialog text score incomplete (lost a life)\",\"default\":\"You did not achieve full score and lost a life.\"},{\"name\":\"confirmFullScoreHeader\",\"type\":\"text\",\"label\":\"Dialog header full score\",\"default\":\"You achieved full score!\"},{\"name\":\"confirmFullScoreDialog\",\"type\":\"text\",\"label\":\"Dialog text full score\",\"default\":\"You have collected enough points to finish this map with a full score, but you are free to explore the rest if you wish to. Your score will be submitted once you finish the map.\"},{\"name\":\"confirmFullScoreDialogLoseLivesAmendmend\",\"type\":\"text\",\"label\":\"Dialog text full score (amendment, if lives are set)\",\"default\":\"But beware! You may still lose lives!\"},{\"name\":\"ok\",\"type\":\"text\",\"label\":\"OK\",\"default\":\"OK\"},{\"name\":\"noStages\",\"type\":\"text\",\"label\":\"No stages were set\",\"default\":\"No valid stages were set for the map.\"},{\"name\":\"settings\",\"type\":\"text\",\"label\":\"Settings\",\"default\":\"Settings\"},{\"name\":\"volumeMusic\",\"type\":\"text\",\"label\":\"Volume of music\",\"default\":\"Volume of music\"},{\"name\":\"volumeSFX\",\"type\":\"text\",\"label\":\"Volume of sound effects\",\"default\":\"Volume of sound effects\"},{\"name\":\"restrictionsAllOfLong\",\"type\":\"text\",\"label\":\"The stage will not be available unless\",\"default\":\"The stage will not be available unless:\"},{\"name\":\"restrictionsAnyOfLong\",\"type\":\"text\",\"label\":\"The stage will not be available unless any of\",\"default\":\"The stage will not be available unless any of:\"},{\"name\":\"restrictionsAllOf\",\"type\":\"text\",\"label\":\"All of:\",\"default\":\"All of:\"},{\"name\":\"restrictionsAnyOf\",\"type\":\"text\",\"label\":\"Any of:\",\"default\":\"Any of:\"},{\"name\":\"restrictionTotalScoreLessThan\",\"type\":\"text\",\"label\":\"Total score less than\",\"default\":\"You have a total score less than @value.\"},{\"name\":\"restrictionTotalScoreEqualTo\",\"type\":\"text\",\"label\":\"Total score equal to\",\"default\":\"You have a total score equal to @value.\"},{\"name\":\"restrictionTotalScoreNotEqualTo\",\"type\":\"text\",\"label\":\"Total score not equal to\",\"default\":\"You have a total score not equal to @value.\"},{\"name\":\"restrictionTotalScoreGreaterThan\",\"type\":\"text\",\"label\":\"Total score greater than\",\"default\":\"You have a total score greater than @value.\"},{\"name\":\"restrictionStageScoreLessThan\",\"type\":\"text\",\"label\":\"Stage score less than\",\"default\":\"You have a score less than @value in stage @label.\"},{\"name\":\"restrictionStageScoreEqualTo\",\"type\":\"text\",\"label\":\"Stage score equal to\",\"default\":\"You have a score equal to @value in stage @label.\"},{\"name\":\"restrictionStageScoreNotEqualTo\",\"type\":\"text\",\"label\":\"Stage score not equal to\",\"default\":\"You have a score not equal to @value in stage @label.\"},{\"name\":\"restrictionStageScoreGreaterThan\",\"type\":\"text\",\"label\":\"Stage score greater than\",\"default\":\"You have a score greater than @value in stage @label.\"},{\"name\":\"restrictionStageProgressIs\",\"type\":\"text\",\"label\":\"Stage progress is\",\"default\":\"The progress of stage @label is @value.\"},{\"name\":\"restrictionStageProgressIsNot\",\"type\":\"text\",\"label\":\"Stage progress is not\",\"default\":\"Ths progress of stage @label is not @value.\"},{\"name\":\"restrictionTimeBefore\",\"type\":\"text\",\"label\":\"Time before\",\"default\":\"The current time is before @value.\"},{\"name\":\"restrictionTimeOn\",\"type\":\"text\",\"label\":\"Time is\",\"default\":\"The current time is @value.\"},{\"name\":\"restrictionTimeNotOn\",\"type\":\"text\",\"label\":\"Time is not\",\"default\":\"The current time is not @value.\"},{\"name\":\"restrictionTimeAfter\",\"type\":\"text\",\"label\":\"Time after\",\"default\":\"The current time is after @value.\"},{\"name\":\"unstarted\",\"type\":\"text\",\"label\":\"Not started\",\"default\":\"not started\"},{\"name\":\"opened\",\"type\":\"text\",\"label\":\"Started\",\"default\":\"started\"},{\"name\":\"completed\",\"type\":\"text\",\"label\":\"Completed\",\"default\":\"completed\"},{\"name\":\"cleared\",\"type\":\"text\",\"label\":\"Completed successfully\",\"default\":\"completed successfully\"},{\"name\":\"missingContent\",\"type\":\"text\",\"label\":\"Missing content\",\"default\":\"No content was set for this stage!\"}]},{\"name\":\"a11y\",\"type\":\"group\",\"label\":\"Accessibility texts\",\"common\":true,\"fields\":[{\"name\":\"buttonFinish\",\"type\":\"text\",\"label\":\"Finish\",\"default\":\"Finish the map\"},{\"name\":\"buttonAudioActive\",\"type\":\"text\",\"label\":\"Audio button (unmuted)\",\"default\":\"Mute audio. Currently unmuted.\"},{\"name\":\"buttonAudioInactive\",\"type\":\"text\",\"label\":\"Audio button (muted)\",\"default\":\"Unmute audio. Currently muted.\"},{\"name\":\"close\",\"type\":\"text\",\"label\":\"Close\",\"default\":\"Close\"},{\"name\":\"yourResult\",\"type\":\"text\",\"label\":\"Your result\",\"description\":\"@score will be replaced by the number of points. @total will be replaced by the maximum possible points.\",\"default\":\"You got @score out of @total points\"},{\"name\":\"mapWasOpened\",\"type\":\"text\",\"label\":\"Map was opened\",\"default\":\"The map was opened.\"},{\"name\":\"mapSolutionsWasOpened\",\"type\":\"text\",\"label\":\"Map was opened (solutions mode)\",\"default\":\"The map was opened in solutions mode.\"},{\"name\":\"startScreenWasOpened\",\"type\":\"text\",\"label\":\"Title screen was opened\",\"default\":\"The title screen was opened.\"},{\"name\":\"endScreenWasOpened\",\"type\":\"text\",\"label\":\"End screen was opened\",\"default\":\"The end screen was opened.\"},{\"name\":\"exerciseLabel\",\"type\":\"text\",\"label\":\"Exercise label\",\"description\":\"@stagelabel is a placeholder and will be replaced with the respective stage label.\",\"default\":\". Exercise for @stagelabel\"},{\"name\":\"stageButtonLabel\",\"type\":\"text\",\"label\":\"Stage button label\",\"description\":\"@stagelabel is a placeholder and will be replaced with the respective stage label.\",\"default\":\"Stage: @stagelabel\"},{\"name\":\"adjacentStageLabel\",\"type\":\"text\",\"label\":\"adjacent stage label\",\"description\":\"@stagelabelOrigin and @stagelabelNeighbor are placeholders and will be replaced with the respective stage labels.\",\"default\":\"Adjacent stage of @stagelabelOrigin: @stagelabelNeighbor\"},{\"name\":\"locked\",\"type\":\"text\",\"label\":\"Locked\",\"default\":\"Locked\"},{\"name\":\"cleared\",\"type\":\"text\",\"label\":\"Cleared\",\"default\":\"Cleared\"},{\"name\":\"applicationInstructions\",\"type\":\"text\",\"label\":\"Description of map navigation\",\"default\":\"Use space or enter key to activate current stage. Use arrow keys to select adjacent stage. Use space or enter key on adjacent stage to navigate there.\"},{\"name\":\"applicationDescription\",\"type\":\"text\",\"label\":\"Description of map\",\"default\":\"Map\"},{\"name\":\"movedToStage\",\"type\":\"text\",\"label\":\"Moved to stage\",\"description\":\"@stagelabel is a placeholder and will be replaced with the respective stage label.\",\"default\":\"Moved to @stagelabel\"},{\"name\":\"stageUnlocked\",\"type\":\"text\",\"label\":\"Unlocked stage\",\"description\":\"@stagelabel is a placeholder and will be replaced with the respective stage label.\",\"default\":\"Stage @stagelabel was unlocked.\"},{\"name\":\"toolbarFallbackLabel\",\"type\":\"text\",\"label\":\"Toolbar fallback label\",\"default\":\"Game Map\"},{\"name\":\"enterFullscreen\",\"type\":\"text\",\"label\":\"Enter fullscreen\",\"default\":\"Enter fullscreen mode\"},{\"name\":\"exitFullscreen\",\"type\":\"text\",\"label\":\"Exit fullscreen\",\"default\":\"Exit fullscreen mode\"}]}]\n',NULL,1,27,NULL,NULL,'https://h5p.org/content-types/game-map',1),
(144,'H5P.SoundJS','Sound js api',1,0,2,0,0,'','soundjs-0.6.2.min.js','','','',NULL,NULL,NULL,NULL,NULL,NULL,1),
(145,'H5P.FindTheWords','Find The Words',1,4,4,1,0,'iframe','scripts/h5p-find-the-words.js, scripts/h5p-find-the-words-word-grid.js, scripts/h5p-find-the-words-vocabulary.js, scripts/h5p-find-the-words-timer.js, scripts/h5p-find-the-words-counter.js','styles/h5p-find-the-words.css','','[\n  {\n    \"label\": \"Task description\",\n    \"name\": \"taskDescription\",\n    \"type\": \"text\",\n    \"description\": \"Description of the Game\",\n    \"default\": \"Find the words from the grid\",\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"wordList\",\n    \"type\": \"text\",\n    \"label\": \"Word list\",\n    \"description\": \"Comma Separated list of words. Special Characters, White Spaces and Numbers Not allowed\",\n    \"default\": \"one,two,three\",\n    \"regexp\": {\n      \"pattern\": \"^(?!(?:.*[\\\"!#$%&./:;<=>?@\\\\[\\\\]^_`\\\\{|}~\'()\\\\-*+\\\\d]|^[,])).*$\"\n    },\n    \"importance\": \"high\"\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the game behaves.\",\n    \"optional\": true,\n    \"fields\": [\n      {\n        \"name\": \"orientations\",\n        \"type\": \"group\",\n        \"label\": \"Orientations\",\n        \"description\": \"An array containing the names of the word directions that should be used when creating the puzzle\",\n        \"fields\": [\n          {\n            \"name\": \"horizontal\",\n            \"type\": \"boolean\",\n            \"label\": \"Horizontal- left to right\",\n            \"default\": true\n          },\n          {\n            \"name\": \"horizontalBack\",\n            \"type\": \"boolean\",\n            \"label\": \"Horizontal- right to left\",\n            \"default\": true\n          },\n          {\n            \"name\": \"vertical\",\n            \"type\": \"boolean\",\n            \"label\": \"Vertical downwards\",\n            \"default\": true\n          },\n          {\n            \"name\": \"verticalUp\",\n            \"type\": \"boolean\",\n            \"label\": \"Vertical upwards\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonal\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal downwards- left to right\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonalBack\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal downwards- right to left\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonalUp\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal upwards- left to right\",\n            \"default\": true\n          },\n          {\n            \"name\": \"diagonalUpBack\",\n            \"type\": \"boolean\",\n            \"label\": \"Diagonal upwards- right to left\",\n            \"default\": true\n          }\n        ]\n      },\n      {\n        \"name\": \"fillPool\",\n        \"type\": \"text\",\n        \"label\": \"Vertical downwards\",\n        \"description\": \"pool of letters from which the blanks to be filled\",\n        \"default\": \"abcdefghijklmnopqrstuvwxyz\",\n        \"regexp\": {\n          \"pattern\": \"^[^\\t\\n .<>?;:\\\"\'`!@#$%^&*()\\\\[\\\\]{}_+=|\\\\-]*$\"\n        }\n      },\n      {\n        \"name\": \"preferOverlap\",\n        \"type\": \"boolean\",\n        \"label\": \"Prefer overlap\",\n        \"description\": \"Determines how wordfind decides where to place a word within the puzzle.   When true, it randomly selects amongst the positions the highest number of letters that overlap creating a more compact puzzle.   When false, it randomly selects amongst all valid positions creating a less compact puzzle.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"showVocabulary\",\n        \"type\": \"boolean\",\n        \"label\": \"Show vocabulary\",\n        \"description\": \"Determines whether to show vocabularies to the player\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableShowSolution\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable show solution\",\n        \"description\": \"Add a show solution button for the game\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable retry\",\n        \"description\": \"Add a retry button for the game\",\n        \"default\": true\n      }\n    ]\n  },\n  {\n    \"label\": \"Localization\",\n    \"importance\": \"low\",\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"fields\": [\n      {\n        \"label\": \"Text for \\\"Check\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"check\",\n        \"type\": \"text\",\n        \"default\": \"Check\"\n      },\n      {\n        \"label\": \"Text for \\\"Retry\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"tryAgain\",\n        \"type\": \"text\",\n        \"default\": \"Retry\"\n      },\n      {\n        \"label\": \"Text for \\\"Show Solution\\\" button\",\n        \"importance\": \"low\",\n        \"name\": \"showSolution\",\n        \"type\": \"text\",\n        \"default\": \"Show Solution\"\n      },\n      {\n        \"label\": \"Counter text\",\n        \"importance\": \"low\",\n        \"name\": \"found\",\n        \"type\": \"text\",\n        \"default\": \"@found of @totalWords found\",\n        \"description\": \"Feedback text, variables available: @found and @totalWords. Example: \'@found of @totalWords found\'\"\n      },\n      {\n        \"label\": \"Time spent text\",\n        \"importance\": \"low\",\n        \"name\": \"timeSpent\",\n        \"type\": \"text\",\n        \"default\": \"Time Spent\",\n        \"description\": \"label for showing the time spent while playing the game\"\n      },\n      {\n        \"label\": \"Feedback text\",\n        \"importance\": \"low\",\n        \"name\": \"score\",\n        \"type\": \"text\",\n        \"default\": \"You got @score of @total points\",\n        \"description\": \"Feedback text, variables available: @score and @total. Example: \'You got @score of @total possible points\'\"\n      },\n      {\n        \"label\": \"Word list header\",\n        \"importance\": \"low\",\n        \"name\": \"wordListHeader\",\n        \"type\": \"text\",\n        \"default\": \"Find the words\",\n        \"maxLength\": 20\n      }\n    ]\n  }\n]\n',NULL,NULL,NULL,NULL,NULL,'https://h5p.org/find-the-words',1);
