INSERT INTO `m_resource` VALUES
(3,48,'📄 Fiche mémo PDF — Synthèse & Glossaire (Domaine 1 Bronze)','<p>Téléchargez et conservez votre <strong>Fiche mémo officielle (PDF)</strong> regroupant les 7 points clés à retenir, les Fiches de synthèse 1 et 2 (Android, Windows 11, Ubuntu 24.04) et le Glossaire des 15 termes du module.</p>',1,0,0,NULL,0,'a:4:{s:8:\"showsize\";i:1;s:8:\"showtype\";i:1;s:8:\"showdate\";i:1;s:10:\"printintro\";i:1;}',0,1,1792492525),
(4,48,'📊 Support de cours complet — Découvrir l\'informatique (Diaporama PowerPoint)','<p>Support visuel complet de la formation (115 diapositives illustrées : cours, démonstrations pas à pas, 7 pratiques en binôme, travaux de groupe, fiches de synthèse et glossaire).</p>',1,0,0,NULL,0,'a:4:{s:8:\"showsize\";i:1;s:8:\"showtype\";i:1;s:8:\"showdate\";i:1;s:10:\"printintro\";i:1;}',0,1,1792492525),
(5,48,'📘 Guide du formateur — Domaine 1 Module Bronze (Scénario & Animation)','<p>Guide pédagogique officiel du formateur : préparation de la salle la veille, déroulé minute par minute des 8 séquences (6 h), réponses aux questions fréquentes, variantes avec peu ou pas d\'appareils et grille d\'observation des 7 pratiques.</p>',1,0,0,NULL,0,'a:4:{s:8:\"showsize\";i:1;s:8:\"showtype\";i:1;s:8:\"showdate\";i:1;s:10:\"printintro\";i:1;}',0,1,1792492525),
(6,48,'🔑 Corrigé & Barème — Évaluation des apprenants D1 Bronze (QCM + 7 tâches pratiques)','<p>Document officiel d\'évaluation comprenant le sujet papier des 21 QCM (Partie A), les 7 épreuves pratiques en circuit avec grilles de critères Acquis / Non acquis (Partie B), la fiche individuelle de résultats, le barème (seuil 70 %), le protocole de remédiation et le corrigé complet réservé au formateur.</p>',1,0,0,NULL,0,'a:4:{s:8:\"showsize\";i:1;s:8:\"showtype\";i:1;s:8:\"showdate\";i:1;s:10:\"printintro\";i:1;}',0,1,1792492525);
