(3036,'fr',3,'location','Location','Lieu',NULL,1792162273,NULL,0,0),
(3037,'fr',3,'locationsettings','Location settings','Réglages lieu',NULL,1792162273,NULL,0,0),
(3038,'fr',3,'locked','Locked','Verrouillé',NULL,1792162273,NULL,0,0),
(3039,'fr',3,'lockoutduration','Account lockout duration','Durée de blocage du compte',NULL,1792162273,NULL,0,0),
(3040,'fr',3,'lockoutduration_desc','Locked out account is automatically unlocked after this duration.','Les comptes bloqués seront automatiquement débloqués une fois cette durée écoulée',NULL,1792162273,NULL,0,0),
(3041,'fr',3,'lockoutemailbody','Hi {$a->firstname},\n\nYour account with username {$a->username} on server \'{$a->sitename}\'\nwas locked out after multiple invalid login attempts.\n\nTo unlock the account immediately, please click the link below:\n\n<a href=\"{$a->link}\">Unlock account</a>\n\n\nIf you need help, please contact the site administrator.\n{$a->admin}','Bonjour {$a->firstname},\n\nVotre compte utilisateur « {$a->username} » sur le serveur « {$a->sitename} » a été bloqué suite à plusieurs tentatives de connexion non valides.\n\nPour débloquer votre compte immédiatement, veuillez cliquer le lien ci-dessous :\n\n<a href=\"{$a->link}\">Débloquer le compte</a>\n\nSi vous avez besoin d’aide, veuillez contacter l’administrateur du site,\n{$a->admin}',NULL,1792162273,NULL,0,0),
(3042,'fr',3,'lockoutemailsubject','Your account on {$a} was locked out','Votre compte sur {$a} a été bloqué',NULL,1792162273,NULL,0,0),
(3043,'fr',3,'lockouterrorunlock','Invalid account unlock information supplied.','Information de déblocage du compte non valide.',NULL,1792162273,NULL,0,0),
(3044,'fr',3,'lockoutthreshold','Account lockout threshold','Limite pour blocage de compte',NULL,1792162273,NULL,0,0),
(3045,'fr',3,'lockoutthreshold_desc','Select number of failed login attempts that result in account lockout. This feature may be abused in denial of service attacks.','Indiquer le nombre de tentatives infructueuses successives de connexion déclenchant le blocage du compte. Cette fonctionnalité peut être utilisée lors d’attaques en déni de service.',NULL,1792162273,NULL,0,0),
(3046,'fr',3,'lockoutwindow','Account lockout observation window','Période d’observation pour blocage des comptes',NULL,1792162273,NULL,0,0),
(3047,'fr',3,'lockoutwindow_desc','Observation time for lockout threshold, if there are no failed attempts the threshold counter is reset after this time.','Période durant laquelle le nombre de tentatives infructueuses successives de connexion est contrôlé. Si aucune nouvelle tentative infructueuse n’a lieu durant cette période, le compteur est remis à zéro.',NULL,1792162273,NULL,0,0),
(3048,'fr',3,'lockrequestcategory','Prevent category selection','Empêcher la sélection d’une catégorie',NULL,1792162273,NULL,0,0),
(3049,'fr',3,'log','Logs','Journaux',NULL,1792162273,NULL,0,0),
(3050,'fr',3,'logguests','Log guest access','Enregistrer les journaux de l’utilisateur anonyme',NULL,1792162273,NULL,0,0),
(3051,'fr',3,'logguests_help','This setting enables logging of actions by guest account and not logged in users. High profile sites may want to disable this logging for performance reasons. It is recommended to keep this setting enabled on production sites.','Ce réglage permet d’enregistrer les actions du compte utilisateur anonyme et des utilisateurs non authentifiés. Les sites avec un grand trafic de visiteurs anonymes devraient désactiver cette option en cas de baisse de performance. Il est recommandé d’activer ce réglage sur les sites en production.',NULL,1792162273,NULL,0,0),
(3052,'fr',3,'logininfoinsecurelayout','Display logged-in user in secure layout','Afficher le nom de l’utilisateur connecté dans l’affichage sécurisé',NULL,1792162273,NULL,0,0),
(3053,'fr',3,'logininfoinsecurelayout_desc','If enabled, the logged-in user\'s full name will be displayed in the navigation bar when attempting a quiz or other activity using secure layout.','Si ce réglage est activé, le nom complet de l’utilisateur est affiché dans la barre de navigation lors de la participation à un test ou à une autre activité utilisant l’affichage sécurisé.',NULL,1792162273,NULL,0,0),
(3054,'fr',3,'loginpageautofocus','Autofocus login page form','Curseur automatique dans les champs du formulaire de connexion',NULL,1792162273,NULL,0,0),
(3055,'fr',3,'loginpageautofocus_help','Enabling this option improves usability of the login page, but automatically focusing fields may be considered an accessibility issue.','L’activation de ce réglage améliore l’ergonomie de la page de connexion, au prix d’une accessibilité diminuée (car le placement automatique du curseur dans les champs de saisie n’est pas toujours accessible).',NULL,1792162273,NULL,0,0),
(3056,'fr',3,'loglifetime','Keep logs for','Conserver les journaux durant',NULL,1792162273,NULL,0,0),
(3057,'fr',3,'logo','Logo','Logo',NULL,1792162273,NULL,0,0),
(3058,'fr',3,'logo_desc','A full logo to be used as decoration by some themes (such as core themes). This image can be quite high resolution because it will be scaled down for use (and cached for performance). Logos that are wider than they are high usually give better results.','Un logo ou logotype qui sera utilisé par certains thèmes. Cette image peut être en haute résolution, car elle sera mise à l’échelle (et mise en cache pour augmenter la performance). Les logos plus larges que long donnent de meilleurs résultats.',NULL,1792162273,NULL,0,0),
(3059,'fr',3,'logocompact','Compact logo','Logo compact',NULL,1792162273,NULL,0,0),
(3060,'fr',3,'logocompact_desc','A compact version of the same logo as above, such as an emblem, shield or icon. The image should be clear even at small sizes.','Une version compacte du même logo que ci-dessus, par exemple une icône ou un emblême. L’image doit être lisible même en petite taille.',NULL,1792162273,NULL,0,0),
(3061,'fr',3,'logossettings','Logos','Logos',NULL,1792162273,NULL,0,0),
(3062,'fr',3,'logstorenotrequired','Log store not required','Stockage de journaux non requis',NULL,1792162273,NULL,0,0),
(3063,'fr',3,'logstoressupported','Log stores that support this report','Stockages de journaux permettant ce rapport',NULL,1792162273,NULL,0,0),
