(3189,'fr',3,'numberofstrings','Total number of strings: {$a->strings}<br />Missing: {$a->missing} ({$a->missingpercent}&nbsp;%)','Nombre total de chaînes de caractères : {$a->strings}<br />Manquantes : {$a->missing} ({$a->missingpercent} %)',NULL,1792162273,NULL,0,0),
(3190,'fr',3,'oauthrefreshtokenexpired','The refresh token for an OAuth 2 service {$a->issuer} on your site {$a->siteurl} has expired. This will limit the functionality of any plugins that use this service. To fix it, go to the OAuth 2 Services configuration page and click the \"Connect system account\" icon in the table row for this service. Be sure to log in using the same service account for the OAuth 2 system each time.','Le jeton d’actualisation pour un service OAuth {$a->issuer} de votre site {$a->siteurl} est échu. Par conséquent, les fonctionnalités des plugins qui utilisent ce service seront limitées. Pour corriger ceci, visitez la page de configuration des services OAuth 2 et cliquez sur l’icône « Connect system account » dans la rangée correspondant à ce service. Assurez-vous de vous connecter à chaque fois avec le même compte de service de OAuth.',NULL,1792162273,NULL,0,0),
(3191,'fr',3,'oauthrefreshtokenexpiredshort','OAuth refresh token expired for {$a->issuer} on your site {$a->siteurl}.','Jeton d’actualisation échu pour {$a->issuer} sur votre site {$a->siteurl}.',NULL,1792162273,NULL,0,0),
