(3334,'fr',3,'proxytype','Proxy type','Type de proxy',NULL,1792162273,NULL,0,0),
(3335,'fr',3,'proxyuser','Proxy username','Nom d’utilisateur du proxy',NULL,1792162273,NULL,0,0),
(3336,'fr',3,'proxylogunsafe','Log unproxied calls','Journaliser les appels sans proxy',NULL,1792162273,NULL,0,0),
(3337,'fr',3,'proxyfixunsafe','Fix unproxied calls','Corriger les appels sans proxy',NULL,1792162273,NULL,0,0),
