INSERT INTO `m_tool_customlang` VALUES
(5670,'fr',15,'privacy:metadata:cachestore','The Cache subsystem stores data temporarily on behalf of other parts of Moodle. This data is not easily identifiable, and is very short lived. It serves as a cache of data stored elsewhere in Moodle, and should therefore already be handled by those Moodle components.','Le sous-système Cache enregistre temporairement des données pour d’autres parties de Moodle. Il sert comme cache de données déjà enregistrées ailleurs dans Moodle, et sont donc en principe déjà traitées par ces composants de Moodle. Ces données sont difficilement identifiables et leur durée de vie est très courte.',NULL,1792162274,NULL,0,0),
(5671,'fr',15,'purge','Purge','Purger',NULL,1792162274,NULL,0,0),
(5672,'fr',15,'purgeagain','Purge again','Purger à nouveau',NULL,1792162274,NULL,0,0),
