(8541,'fr',33,'pluginrequirementsnotmet','Plugin \"{$a->pluginname}\" ({$a->pluginversion}) could not be installed.  It requires a newer version of Moodle (currently you are using {$a->currentmoodle}, you need {$a->requiremoodle}).','Le plugin « {$a->pluginname} » ({$a->pluginversion}) ne peut pas être installé. Il nécessite une version plus récente de Moodle (vous utilisez actuellement la version {$a->currentmoodle}, la version {$a->requiremoodle} est requise)',NULL,1792162274,NULL,0,0),
(8542,'fr',33,'pluginunsupported','Plugin \"{$a->pluginname}\" {$a->pluginversion} does not support this version of Moodle {$a->moodleversion}. Seek plugin information to find supported versions.','Le plugin « {$a->pluginname} » {$a->pluginversion} ne prend pas en charge cette version de Moodle {$a->moodleversion}. Veuillez consulter les informations du plugin pour trouver les versions prises en charge.',NULL,1792162274,NULL,0,0),
(8543,'fr',33,'prefixcannotbeempty','<p>Error: database table prefix cannot be empty ({$a})</p>\n<p>The site administrator must fix this problem.</p>','<p>Erreur : le préfixe des tables de la base de données ne peut pas être vide ({$a}).</p><p>L’administrateur du site doit corriger ce problème.</p>',NULL,1792162274,NULL,0,0),
(8544,'fr',33,'privatefilesupload','Uploading directly to user private files area is no longer supported. Upload to a draft area and then move the files with core_user::add_user_private_files','Le dépôt de fichier directement dans la zone des fichiers personnels n’est plus pris en charge. Veuillez déposer les fichiers vers la zone de brouillon, puis les déplacer avec core_user::add_user_private_files',NULL,1792162274,NULL,0,0),
