(9161,'fr',41,'grademax','Maximum grade','Note maximale',NULL,1792162274,NULL,0,0),
(9162,'fr',41,'grademax_help','This setting determines the maximum grade when using the value grade type. The maximum grade for an activity-based grade item is set on the activity settings page.','Ce réglage détermine la note maximale lorsque le type de note est une valeur. La note maximale pour un élément d’évaluation basé sur une activité est gérée dans les paramètres de l’activité.',NULL,1792162274,NULL,0,0),
(9163,'fr',41,'grademin','Minimum grade','Note minimale',NULL,1792162274,NULL,0,0),
(9164,'fr',41,'grademin_help','This setting determines the minimum grade when using the value grade type.','Ce réglage détermine la note minimale lorsque le type de note est une valeur.',NULL,1792162274,NULL,0,0),
(9165,'fr',41,'gradenotificationmessage','You have new feedback on your work for \"{$a}\"','Vous avez un nouveau feedback pour votre travail dans « {$a} »',NULL,1792162274,NULL,0,0),
(9166,'fr',41,'gradenotificationsubject','You have been graded','Vous avez été évalué',NULL,1792162274,NULL,0,0),
(9167,'fr',41,'gradeoutcomeitem','Grade outcome item','Évaluer élément d’objectif',NULL,1792162274,NULL,0,0),
(9168,'fr',41,'gradeoutcomes','Outcomes','Objectifs',NULL,1792162274,NULL,0,0),
