(10326,'fr',46,'restartregistration','Restart registration','Recommencer l’enregistrement',NULL,1792162275,NULL,0,0),
(10327,'fr',46,'roleassignmentsnumber','Number of role assignments ({$a})','Nombre d’attributions de rôles ({$a})',NULL,1792162275,NULL,0,0),
(10328,'fr',46,'search','Search','Recherche',NULL,1792162275,NULL,0,0),
(10329,'fr',46,'sendingsize','Please wait the course file is uploading ({$a->total}Mb)...','Veuillez patienter durant l’envoi du fichier de cours ({$a->total} Mo)…',NULL,1792162275,NULL,0,0),
(10330,'fr',46,'sendfollowinginfo','More information','Plus d’informations',NULL,1792162275,NULL,0,0),
(10331,'fr',46,'sendfollowinginfo_help','The following information will be sent to Moodle each time your site registration is updated (by default weekly, when the \'Site registration\' scheduled task is run). The information contributes to overall statistics only and will not be made public on any site listing. In addition, your Moodle release version is recorded by the weekly automated site link check.','Les informations suivantes seront envoyées à Moodle à chaque fois que l’enregistrement de votre site sera actualisé (par défaut, chaque semaine, lorsque la tâche programmée « Enregistrement du site » est lancée). Ces informations ne sont utilisées que pour constituer des statistiques globales, et aucune d’entre elles ne sont rendues publiques. De plus, la version de votre Moodle est enregistrée chaque semaine au moyen d’un contrôle automatique de liens.',NULL,1792162275,NULL,0,0),
(10332,'fr',46,'sent','...finished','… terminé',NULL,1792162275,NULL,0,0),
(10333,'fr',46,'siteadmin','Administrator','Administrateur',NULL,1792162275,NULL,0,0),
(10334,'fr',46,'siteadmin_help','The full name of the site administrator.','Le nom complet de l’administrateur du site.',NULL,1792162275,NULL,0,0),
