INSERT INTO `m_tool_customlang` VALUES
(12636,'fr',66,'manualgradeinvalidformat','That is not a valid number.','Ce nombre n’est pas valide.',NULL,1792162275,NULL,0,0),
(12637,'fr',66,'matchgrades','Match grades','Faire correspondre les notes',NULL,1792162275,NULL,0,0),
(12638,'fr',66,'matchgradeserror','Error if grade not listed','Erreur si la note n’est pas listée',NULL,1792162275,NULL,0,0),
(12639,'fr',66,'matchgradesnearest','Nearest grade if not listed','Note la plus proche si elle n’est pas listée',NULL,1792162275,NULL,0,0),
(12640,'fr',66,'matchgrades_help','Imported grades must match one of the fixed list of valid grades - 100, 90, 80, 75, 70, 66.666, 60, 50, 40, 33.333, 30, 25, 20, 16.666, 14.2857, 12.5, 11.111, 10, 5, 0 (also negative values). If not, there are two options:\n\n*  Error if grade not listed - If a question contains any grades not found in the list an error is displayed and that question will not be imported\n* Nearest grade if not listed - If a grade is found that does not match a value in the list, the grade is changed to the closest matching value in the list ','Les notes importées doivent correspondre à la liste des notes acceptables : 100, 90, 80, 75, 70, 66.666, 60, 50, 40, 33.333, 30, 25, 20, 16.666, 14.2857, 12.5, 11.111, 10, 5, 0. Des valeurs négatives sont également permises. Dans le cas contraire, il y a deux options :\n\n* erreur si la note n’est pas répertoriée : si une question prévoit une note qui n’est pas répertoriée dans la liste, une erreur est affichée et la question n’est pas importée ;\n* note la plus proche si elle n’est pas répertoriée : si une note ne correspond à celles prévues dans la liste, elle est adaptée à la valeur la plus proche de la liste.',NULL,1792162275,NULL,0,0),
(12641,'fr',66,'missingcourseorcmid','Need to provide courseid or cmid to print_question.','Vous devez fournir l’identifiant de cours ou le numéro de cours pour imprimer la question.',NULL,1792162275,NULL,0,0),
(12642,'fr',66,'missingcourseorcmidtolink','Need to provide courseid or cmid to get_question_edit_link.','Vous devez fournir l’identifiant de cours ou le numéro de cours à get_question_edit_link.',NULL,1792162275,NULL,0,0),
(12643,'fr',66,'missingimportantcode','This question type is missing important code: {$a}.','Il manque à ce type de question un code important : {$a}.',NULL,1792162275,NULL,0,0),
