(12653,'fr',66,'movingcategory','Moving category','Déplacement catégorie',NULL,1792162275,NULL,0,0),
(12654,'fr',66,'movingcategoryandfiles','Are you sure you want to move category {$a->name} and all child categories to context for \"{$a->contextto}\"?<br /> We have detected {$a->urlcount} files linked from questions in {$a->fromareaname}, would you like to copy or move these to {$a->toareaname}?','Voulez-vous vraiment déplacer la catégorie {$a->name} et toutes les catégories filles vers le contexte « {$a->contextto} »?<br />{$a->urlcount} fichiers liés depuis des questions situées dans {$a->fromareaname} ont été détectés. Voulez-vous les copier ou les déplacer vers {$a->toareaname} ?',NULL,1792162275,NULL,0,0),
(12655,'fr',66,'movingcategorynofiles','Are you sure you want to move category \"{$a->name}\" and all child categories to context for \"{$a->contextto}\"?','Voulez-vous vraiment déplacer la catégorie {$a->name} et toutes les catégories filles vers le contexte « {$a->contextto} » ?',NULL,1792162275,NULL,0,0),
(12656,'fr',66,'movingquestions','Moving questions and any files','Déplacement des questions et des fichiers',NULL,1792162275,NULL,0,0),
(12657,'fr',66,'movingquestionsandfiles','Are you sure you want to move question(s) {$a->questions} to context for <strong>\"{$a->tocontext}\"</strong>?<br /> We have detected <strong>{$a->urlcount} files</strong> linked from these question(s) in {$a->fromareaname}, would you like to copy or move these to {$a->toareaname}?','Voulez-vous vraiment déplacer la(les) question(s) {$a->questions} vers le contexte « {$a->tocontext} »?<br />{$a->urlcount} fichiers liés depuis cette(ces) question(s) dans {$a->fromareaname} ont été détectés. Voulez-vous les copier ou les déplacer vers {$a->toareaname} ',NULL,1792162275,NULL,0,0),
(12658,'fr',66,'movingquestionsnofiles','Are you sure you want to move question(s) {$a->questions} to context for <strong>\"{$a->tocontext}\"</strong>?<br /> There are <strong>no files</strong> linked from these question(s) in {$a->fromareaname}.','Voulez-vous vraiment déplacer la(les) question(s) {$a->questions} vers le contexte « {$a->tocontext} »?<br />Il n’y a <strong>aucun fichier</strong> liés depuis cette(ces) question(s) dans {$a->fromareaname}.',NULL,1792162275,NULL,0,0),
(12659,'fr',66,'needtochoosecat','You need to choose a category to move this question to or press \'cancel\'.','Vous devez choisir une catégorie dans laquelle déplacer cette question ou cliquer sur « Annuler ».',NULL,1792162275,NULL,0,0),
