(20433,'fr',127,'deselectallattempts','Deselect all attempts','Désélectionner toutes les tentatives',NULL,1792162277,NULL,0,0),
(20434,'fr',127,'detailedstats','Detailed statistics','Statistiques détaillées',NULL,1792162277,NULL,0,0),
