(21606,'fr',131,'emailconfirmbody','Hi {$a->username},\n\nThank you for submitting your answers to \'{$a->quizname}\' in course \'{$a->coursename}\' at {$a->submissiontime}.\n\nThis message confirms that your answers have been saved.\n\nYou can access this quiz at {$a->quizurl}.','Bonjour {$a->username},\n\nVous avez envoyé vos réponses au test « {$a->quizname} » du cours « {$a->coursename} » à {$a->submissiontime}.\n\nCe message confirme que vos réponses ont été enregistrées.\n\nVous pouvez accéder à ce test en suivant le lien {$a->quizurl}.',NULL,1792162277,NULL,0,0),
(21607,'fr',131,'emailconfirmbodyautosubmit','Hi {$a->username},\n\nThe time for the quiz \'{$a->quizname}\' in the course \'{$a->coursename}\' expired. Your answers were submitted automatically at {$a->submissiontime}.\n\nThis message confirms that your answers have been saved.\n\nYou can access this quiz at {$a->quizurl}.','Bonjour {$a->username},\n\nLe temps imparti pour le test « {$a->quizname} » dans le cours « {$a->coursename} » est arrivé à échéance. Vos réponses ont été envoyées automatiquement à {$a->submissiontime}.\n\nCe message confirme que vos réponses ont été enregistrées.\n\nVous pouvez accéder à ce test via l’adresse {$a->quizurl}.',NULL,1792162277,NULL,0,0),
(21608,'fr',131,'emailconfirmsmall','Thank you for submitting your answers to \'{$a->quizname}\'','Merci pour l’envoi de vos réponses au test « {$a->quizname} »',NULL,1792162277,NULL,0,0),
(21609,'fr',131,'emailconfirmautosubmitsmall','Thank you for submitting your answers to \'{$a->quizname}\'','Merci d’avoir envoyé vos réponses au test « {$a->quizname} »',NULL,1792162277,NULL,0,0),
(21610,'fr',131,'emailconfirmsubject','Submission confirmation: {$a->quizname}','Confirmation d’envoi : {$a->quizname}',NULL,1792162277,NULL,0,0),
(21611,'fr',131,'emailnotifybody','Hi {$a->username},\n\n{$a->studentname} has completed \'{$a->quizname}\' ({$a->quizurl}) in course \'{$a->coursename}\'.\n\nYou can review this attempt at {$a->quizreviewurl}.','Bonjour {$a->username},\n\nLe participant {$a->studentname} a terminé le test « {$a->quizname} » ({$a->quizurl}) du cours « {$a->coursename} ».\n\nVous pouvez voir cette tentative en suivant le lien {$a->quizreviewurl}.',NULL,1792162277,NULL,0,0),
(21612,'fr',131,'emailnotifysmall','{$a->studentname} has completed {$a->quizname}. See {$a->quizreviewurl}','{$a->studentname} a terminé le test {$a->quizname}. Consultez {$a->quizreviewurl}',NULL,1792162277,NULL,0,0),
(21613,'fr',131,'emailnotifysubject','{$a->studentname} has completed {$a->quizname}','Le participant {$a->studentname} a terminé le test {$a->quizname}',NULL,1792162277,NULL,0,0),
(21614,'fr',131,'emailmanualgradedbody','Hi {$a->studentname},\n\nYour answers to \'{$a->quizname}\' in course \'{$a->coursename}\' at {$a->attempttimefinish} have now been graded.\n\nYou will be able to view your score and feedback by visiting \'{$a->quizurl}\' and reviewing your attempt.','Bonjour {$a->studentname},\n\nVos réponses au test « {$a->quizname} » dans le cours « {$a->coursename} » à {$a->attempttimefinish} ont été évaluées.\n\nVous pouvez consulter votre résultat et feedback en visitant « {$a->quizurl} » et relire votre tentative.',NULL,1792162277,NULL,0,0),
(21615,'fr',131,'emailmanualgradedsubject','Your attempt at {$a->quizname} has been graded','Votre tentative du test {$a->quizname} a été évaluée',NULL,1792162277,NULL,0,0),
(21616,'fr',131,'emailoverduebody','Hi {$a->studentname},\n\nYou started an attempt at \'{$a->quizname}\' in course \'{$a->coursename}\', but you never submitted it. It should have been submitted by {$a->attemptduedate}.\n\nIf you would still like to submit this attempt, please go to {$a->attemptsummaryurl} and click the submit button. You must do this before {$a->attemptgraceend} otherwise your attempt will not be counted.','Bonjour {$a->studentname},\n\nVous avez commencé une tentative du test « {$a->quizname} » dans le cours « {$a->coursename} », mais ne l’avez jamais envoyée. Elle aurait dû être envoyée jusqu’au {$a->attemptduedate}.\n\nSi vous voulez envoyer cette tentative, veuillez vous rendre sur {$a->attemptsummaryurl} et cliquer sur le bouton d’envoi.\nVous devez faire ceci avant {$a->attemptgraceend}, sans quoi votre tentative ne sera pas prise en compte.',NULL,1792162277,NULL,0,0),
(21617,'fr',131,'emailoverduesmall','You did not submit your attempt at {$a->quizname}. Please go to {$a->attemptsummaryurl} before {$a->attemptgraceend} if you would still like to submit.','Vous n’avez pas envoyé votre tentative du test {$a->quizname}. Veuillez visiter {$a->attemptsummaryurl} avant {$a->attemptgraceend} si vous désirez l’envoyer.',NULL,1792162277,NULL,0,0),
(21618,'fr',131,'emailoverduesubject','Attempt now overdue: {$a->quizname}','Tentative maintenant en retard : {$a->quizname}',NULL,1792162277,NULL,0,0),
