(23927,'fr',145,'privacy:metadata:auth_oauth2:tableexplanation','OAuth 2 accounts linked to a user\'s Moodle account.','Comptes OAuth 2 liés à un compte d’utilisateur de Moodle.',NULL,1792162278,NULL,0,0),
(23928,'fr',145,'privacy:metadata:auth_oauth2:timecreated','The timestamp when the user account was linked to the OAuth 2 login.','L’horodatage du lien entre le compte utilisateur et le compte OAuth 2.',NULL,1792162278,NULL,0,0),
(23929,'fr',145,'privacy:metadata:auth_oauth2:timemodified','The timestamp when this record was modified.','L’horodatage de la modification de cet enregistrement.',NULL,1792162278,NULL,0,0),
(23930,'fr',145,'privacy:metadata:auth_oauth2:userid','The ID of the user account which the OAuth 2 login is linked to.','L’identifiant du compte utilisateur auquel le compte OAuth 2 est lié.',NULL,1792162278,NULL,0,0),
(23931,'fr',145,'privacy:metadata:auth_oauth2:usermodified','The ID of the user who modified this account.','L’identifiant de l’utilisateur qui a modifié ce compte.',NULL,1792162278,NULL,0,0),
