(24091,'fr',159,'dbhost_desc','Database server IP address or host name. Use a system Data Source Name (DSN) if using Open Database Connectivity (ODBC). Use a PHP Data Objects (PDO) DSN if using PDO.','Saisir l’adresse IP ou le nom d’hôte du serveur de base de données. Si vous utilisez Open Database Connectivity (ODBC), veuillez utiliser une entrée système Data Source Name (DSN). Si vous utilisez PDO, indiquez une entrée DSN PHP Data Objects (PDO).',NULL,1792162278,NULL,0,0),
(24092,'fr',159,'dbname','Database name','Nom de la base de données',NULL,1792162278,NULL,0,0),
(24093,'fr',159,'dbname_desc','Leave empty if using a DSN name in database host.','Laisser vide si vous utilisez un nom DSN sur le serveur de base de données.',NULL,1792162278,NULL,0,0),
(24094,'fr',159,'dbpass','Database password','Mot de passe de la base de données',NULL,1792162278,NULL,0,0),
(24095,'fr',159,'dbsetupsql','Database setup command','Commande de configuration de la base de données',NULL,1792162278,NULL,0,0),
(24096,'fr',159,'dbsetupsql_desc','SQL command for special database setup, often used to setup communication encoding - example for MySQL and PostgreSQL: <em>SET NAMES \'utf8\'</em>','Commande SQL pour une configuration particulière de la base de données. Une telle commande est souvent utilisée pour configurer l’encodage de communication. Par exemple, pour MySQL et PostgreSQL : <em>SET NAMES \'utf8\'</em>',NULL,1792162278,NULL,0,0),
(24097,'fr',159,'dbsybasequoting','Use sybase quotes','Utiliser le mode Sybase pour les apostrophes',NULL,1792162278,NULL,0,0),
(24098,'fr',159,'dbsybasequoting_desc','Sybase style single quote escaping - needed for MS SQL and some other databases. Do not use for MySQL!','Style Sybase pour l’échappement des apostrophes. Ce réglage est nécessaire pour les bases de données MS SQL et d’autres types de base de données. Ne pas utiliser avec MySQL !',NULL,1792162278,NULL,0,0),
(24099,'fr',159,'dbtype','Database driver','Pilote de base de données',NULL,1792162278,NULL,0,0),
(24100,'fr',159,'dbtype_desc','ADOdb database driver name, type of the external database engine.','Nom du pilote de base de données ADOdb, type de moteur de base de données externe.',NULL,1792162278,NULL,0,0),
(24101,'fr',159,'dbuser','Database user','Nom d’utilisateur de la base de données',NULL,1792162278,NULL,0,0),
(24102,'fr',159,'debugdb','Debug ADOdb','Débogage ADOdb',NULL,1792162278,NULL,0,0),
(24103,'fr',159,'debugdb_desc','Debug ADOdb connection to external database - use when getting empty page during login. Not suitable for production sites!','Débogage de la connexion ADOdb vers la base de données externe. À utiliser lorsque vous obtenez une page blanche lors de la connexion à Moodle. Ne convient pas à un site en production !',NULL,1792162278,NULL,0,0),
(24104,'fr',159,'defaultcategory','Default new course category','Catégorie par défaut des nouveaux cours',NULL,1792162278,NULL,0,0),
(24105,'fr',159,'defaultcategory_desc','The default category for auto-created courses. Used when no new category id specified or not found.','La catégorie par défaut pour les cours créés automatiquement. Utilisée lorsqu’aucun identifiant n’est spécifié pour la catégorie ou qu’il n’est pas trouvé.',NULL,1792162278,NULL,0,0),
(24106,'fr',159,'defaultrole','Default role','Rôle par défaut',NULL,1792162278,NULL,0,0),
(24107,'fr',159,'defaultrole_desc','The role that will be assigned by default if no other role is specified in external table.','Rôle devant être attribué par défaut, si aucun autre rôle n’est spécifié dans la base de données externe.',NULL,1792162278,NULL,0,0),
(24108,'fr',159,'ignorehiddencourses','Ignore hidden courses','Ignorer les cours cachés',NULL,1792162278,NULL,0,0),
(24109,'fr',159,'ignorehiddencourses_desc','If enabled users will not be enrolled on courses that are set to be unavailable to students.','Si cette option est activée, les utilisateurs ne seront pas inscrits aux cours non disponibles pour les étudiants.',NULL,1792162278,NULL,0,0),
