(24691,'fr',168,'privacy:metadata:enrol_paypal:paypal_com:country','Country of the user who is buying the course.','Pays de l’utilisateur qui achète le cours.',NULL,1792162278,NULL,0,0),
(24692,'fr',168,'privacy:metadata:enrol_paypal:paypal_com:custom','A hyphen-separated string that contains ID of the user (the buyer), ID of the course, ID of the enrolment instance.','Une liste des identifiants de l’utilisateur (l’acheteur), du cours et de l’instance d’inscription, séparés par des tirets.',NULL,1792162278,NULL,0,0),
(24693,'fr',168,'privacy:metadata:enrol_paypal:paypal_com:email','Email address of the user who is buying the course.','L’adresse de courriel de l’utilisateur qui achète le cours.',NULL,1792162278,NULL,0,0),
(24694,'fr',168,'privacy:metadata:enrol_paypal:paypal_com:first_name','First name of the user who is buying the course.','Le prénom de l’utilisateur qui achète le cours.',NULL,1792162278,NULL,0,0),
(24695,'fr',168,'privacy:metadata:enrol_paypal:paypal_com:last_name','Last name of the user who is buying the course.','Le nom de l’utilisateur qui achète le cours.',NULL,1792162278,NULL,0,0),
(24696,'fr',168,'privacy:metadata:enrol_paypal:paypal_com:os0','Full name of the buyer.','Le nom complet de l’utilisateur qui achète le cours.',NULL,1792162278,NULL,0,0),
