(24777,'fr',169,'usepasswordpolicy','Use password policy','Utiliser la politique de mots de passe',NULL,1792162278,NULL,0,0),
(24778,'fr',169,'usepasswordpolicy_desc','Use standard password policy for enrolment keys.','Utiliser la politique de mots de passe standard pour les clefs d’inscription.',NULL,1792162278,NULL,0,0),
(24779,'fr',169,'privacy:metadata','The Self enrolment plugin does not store any personal data.','Le plugin Auto-inscription n’enregistre aucune donnée personnelle.',NULL,1792162278,NULL,0,0),
