(27532,'fr',339,'certainty2','C=2 (Mid: >67%)','C = 2 (moyennement sûr : > 67%)',NULL,1792162278,NULL,0,0),
(27533,'fr',339,'certainty3','C=3 (Quite sure: >80%)','C = 3 (tout à fait sûr : > 80%)',NULL,1792162278,NULL,0,0),
