(28305,'fr',364,'deleteexistingdeleteduserstask','Create delete data request for pre-existing deleted users','Créer des demandes de suppression de données pour les utilisateurs supprimés antérieurement',NULL,1792162279,NULL,0,0),
(28306,'fr',364,'deletemyaccount','Delete my account','Supprimer mon compte',NULL,1792162279,NULL,0,0),
(28307,'fr',364,'deletepurpose','Delete purpose','Supprimer la finalité',NULL,1792162279,NULL,0,0),
(28308,'fr',364,'deletepurposetext','Are you sure you want to delete the purpose \'{$a}\'?','Voulez-vous vraiment supprimer la finalité « {$a} » ?',NULL,1792162279,NULL,0,0),
(28309,'fr',364,'defaultssaved','Defaults saved','Réglages par défaut enregistrés',NULL,1792162279,NULL,0,0),
