(32276,'fr',488,'resultfailed','Unable to automatically allocate submissions','Impossible d’attribuer automatiquement les travaux',NULL,1792162280,NULL,0,0),
(32277,'fr',488,'resultfailedconfig','Scheduled allocation misconfigured','Attribution programmée mal configurée',NULL,1792162280,NULL,0,0),
