(32761,'fr',507,'email:loginlink','Or, if you\'re on the same device, use this {$a}.','Ou, si vous êtes sur le même appareil, utilisez ce {$a}.',NULL,1792162280,NULL,0,0),
(32762,'fr',507,'email:message','Here\'s your verification code for {$a->sitename} ({$a->siteurl}).','Voici votre code de vérification pour {$a->sitename} ({$a->siteurl}).',NULL,1792162280,NULL,0,0),
