(32767,'fr',507,'email:stoploginlink','stop this login attempt','stopper cette tentative de connexion',NULL,1792162280,NULL,0,0),
(32768,'fr',507,'email:uadescription','Browser identity for this request:','Identité du navigateur de cette requête :',NULL,1792162280,NULL,0,0),
(32769,'fr',507,'email:validity','The code can only be used once and is valid for {$a}.','Le code ne peut être utilisé qu’une seule fois et est valide durant {$a}.',NULL,1792162280,NULL,0,0),
(32770,'fr',507,'error:badcode','Code was not found. This may be an old link, a new code may have been emailed, or the login attempt with this code was successful.','Le code n’a pas été trouvé. Il peut s’agir d’un lien périmé, ou un nouveau code a été envoyé, ou la tentative de connexion avec ce code a réussi.',NULL,1792162280,NULL,0,0),
(32771,'fr',507,'error:parameters','Incorrect page parameters.','Paramètres de page incorrects.',NULL,1792162280,NULL,0,0),
